mapper.select:
SELECT * FROM ddc_list_template WHERE tenant_id=#{tenantId} AND catalog_scope_id=#{scopeId}
  AND page_resource_key=#{pageKey} AND list_key=#{listKey} AND deleted_at IS NULL
  AND (template_type='SYSTEM' OR (template_type='PERSONAL' AND owner_digest=#{ownerDigest}
    AND owner_issuer=#{issuer} AND owner_subject=#{subject})) ORDER BY template_type, template_name, id LIMIT 101

mapper.update:
UPDATE ddc_list_template SET template_name=#{row.templateName},is_default=#{row.defaultTemplate},
  version=version+1,updated_by=#{row.updatedBy},updated_at=#{row.updatedAt}
WHERE tenant_id=#{row.tenantId} AND catalog_scope_id=#{row.catalogScopeId} AND id=#{row.id}
  AND version=#{expectedVersion} AND deleted_at IS NULL

UPDATE ddc_list_template SET is_default=false,version=version+1,updated_by=#{row.updatedBy},updated_at=#{row.updatedAt}
WHERE tenant_id=#{row.tenantId} AND catalog_scope_id=#{row.catalogScopeId} AND page_resource_key=#{row.pageResourceKey}
  AND list_key=#{row.listKey} AND template_type=#{row.templateType} AND owner_digest=#{row.ownerDigest}
  AND owner_issuer=#{row.ownerIssuer} AND owner_subject=#{row.ownerSubject} AND is_default=true
  AND deleted_at IS NULL AND id<>#{row.id}

UPDATE ddc_list_template SET deleted_at=#{now},is_default=false,version=version+1,updated_by=#{actor},updated_at=#{now}
WHERE tenant_id=#{tenantId} AND catalog_scope_id=#{scopeId} AND id=#{id}
  AND version=#{expectedVersion} AND deleted_at IS NULL

